type StatutPaiement = 'Payé' | 'En attente' | 'Échoué' | 'Retard';
type StatutReservation = 'Confirmée' | 'En attente' | 'Échouée' | 'Retard';

interface Paiement {
  id: string;
  reference: string;
  client: string;
  montant: number;
  date: string;
  statut: StatutPaiement;
  motif: string;
}

interface Reservation {
  id: string;
  reference: string;
  client: string;
  service: string;
  montant: number;
  date: string;
  statut: StatutReservation;
}

