const couleurStatut = (statut: string): string => {
  switch (statut) {
    case 'Payé':
    case 'Confirmée':
      return SEMANTIQUE.succes;
    case 'En attente':
      return SEMANTIQUE.attention;
    case 'Retard':
      return SEMANTIQUE.information;
    case 'Échoué':
    case 'Échouée':
    default:
      return SEMANTIQUE.danger;
  }
};

