function EcranAccueil({
  paiements,
  reservations,
  largeur,
}: {
  paiements: Paiement[];
  reservations: Reservation[];
  largeur: number;
}) {
  const totalEncaissé = paiements
    .filter((p) => p.statut === 'Payé')
    .reduce((somme, p) => somme + p.montant, 0);
  const totalAttente = paiements
    .filter((p) => p.statut === 'En attente' || p.statut === 'Retard')
    .reduce((somme, p) => somme + p.montant, 0);
  const totalEchec = paiements
    .filter((p) => p.statut === 'Échoué')
    .reduce((somme, p) => somme + p.montant, 0);
  const reservationsActives = reservations.filter(
    (r) => r.statut === 'Confirmée' || r.statut === 'En attente',
  ).length;

  return (
    <div data-demonstration="true">
      <div style={styles.enteteEcran}>
        <Pastille libelle="Démonstration" couleur={SEMANTIQUE.information} />
      </div>
      <EnTeteDeSection
        titre="Vue d'ensemble des encaissements"
        sousTitre="Suivi des paiements collectés en XAF"
      />

      <div style={styles.grilleCartes}>
        {[
          {
            icone: 'argent',
            libelle: 'Total encaissé',
            valeur: formaterMontant(totalEncaissé),
            contexte: `${paiements.filter((p) => p.statut === 'Payé').length} paiements confirmés`,
          },
          {
            icone: 'horloge',
            libelle: 'En attente',
            valeur: formaterMontant(totalAttente),
            contexte: 'Paiements non soldés',
          },
          {
            icone: 'alerte',
            libelle: 'Échecs',
            valeur: formaterMontant(totalEchec),
            contexte: 'Derniers 7 jours',
          },
          {
            icone: 'document',
            libelle: 'Réservations actives',
            valeur: String(reservationsActives),
            contexte: 'À confirmer ou déjà confirmées',
          },
        ].map((carte, index) => (
          <div
            key={index}
            style={largeur >= 840 ? styles.carteQuart : styles.cartePleine}
          >
            <CarteDeChiffre
              icone={carte.icone}
              libelle={carte.libelle}
              valeur={carte.valeur}
              contexte={carte.contexte}
            />
          </div>
        ))}
      </div>

      <EnTeteDeSection
        titre="Derniers mouvements"
        sousTitre="Encaissements les plus récents"
      />
      {paiements.slice(0, 3).map((p) => (
        <Carte key={p.id}>
          <div style={styles.ligneListe}>
            <div style={styles.colonneGauche}>
              <span style={TYPO.corps}>{p.client}</span>
              <span style={TYPO.petit}>
                {p.reference} · {p.date} · {p.motif}
              </span>
            </div>
            <div style={styles.colonneDroite}>
              <span style={TYPO.corps}>{formaterMontant(p.montant)}</span>
              <Pastille libelle={p.statut} couleur={couleurStatut(p.statut)} />
            </div>
          </div>
        </Carte>
      ))}
    </div>
  );
}

function EcranPaiements({
  paiements,
  onAjouterPaiement,
}: {
  paiements: Paiement[];
  onAjouterPaiement: (client: string, montant: number, motif: string) => void;
}) {
  const [filtre, setFiltre] = useState<'Tous' | StatutPaiement>('Tous');
  const [client, setClient] = useState('');
  const [montant, setMontant] = useState('');
  const [motif, setMotif] = useState('');
  const [erreur, setErreur] = useState('');
  const [message, setMessage] = useState('');

  const paiementsFiltres = useMemo(() => {
    if (filtre === 'Tous') return paiements;
    return paiements.filter((p) => p.statut === filtre);
  }, [paiements, filtre]);

  const enregistrer = () => {
    const montantNombre = Number(montant.replace(',', '.'));
    if (!client.trim() || !montantNombre || !motif.trim()) {
      setErreur('Champs requis : client, montant et motif.');
      setMessage('');
      return;
    }
    onAjouterPaiement(client.trim(), montantNombre, motif.trim());
    setClient('');
    setMontant('');
    setMotif('');
    setErreur('');
    setMessage('Paiement enregistré dans la liste de démonstration.');
  };

  const filtres: Array<'Tous' | StatutPaiement> = [
    'Tous',
    'Payé',
    'En attente',
    'Échoué',
    'Retard',
  ];

  return (
    <div data-demonstration="true">
      <div style={styles.enteteEcran}>
        <Pastille libelle="Démonstration" couleur={SEMANTIQUE.information} />
      </div>
      <EnTeteDeSection
        titre="Encaissements"
        sousTitre="Recouvrement des paiements — XAF"
      />

      <div style={styles.ligneFiltres}>
        {filtres.map((f) => (
          <Bouton
            key={f}
            libelle={f}
            variant={filtre === f ? 'primaire' : 'secondaire'}
            onPress={() => setFiltre(f)}
          />
        ))}
      </div>

      {paiementsFiltres.length === 0 ? (
        <EtatVide
          titre="Aucun paiement"
          description="Modifiez le filtre ou enregistrez un nouveau paiement."
        />
      ) : (
        paiementsFiltres.map((p) => (
          <Carte key={p.id}>
            <div style={styles.ligneListe}>
              <div style={styles.colonneGauche}>
                <span style={TYPO.corps}>{p.client}</span>
                <span style={TYPO.petit}>
                  {p.reference} · {p.date} · {p.motif}
                </span>
              </div>
              <div style={styles.colonneDroite}>
                <span style={TYPO.corps}>{formaterMontant(p.montant)}</span>
                <Pastille libelle={p.statut} couleur={couleurStatut(p.statut)} />
              </div>
            </div>
          </Carte>
        ))
      )}

      <EnTeteDeSection
        titre="Nouveau paiement"
        sousTitre="Encaissement manuel de démonstration"
      />
      <Carte>
        <input
          type="text"
          value={client}
          onChange={(e) => setClient(e.target.value)}
          placeholder="Client"
          style={styles.champTexte}
        />
        <input
          type="text"
          inputMode="numeric"
          value={montant}
          onChange={(e) => setMontant(e.target.value)}
          placeholder="Montant (XAF)"
          style={styles.champTexte}
        />
        <input
          type="text"
          value={motif}
          onChange={(e) => setMotif(e.target.value)}
          placeholder="Motif du paiement"
          style={styles.champTexte}
        />
        {erreur ? <div style={styles.erreur}>{erreur}</div> : null}
        <Bouton
          libelle="Enregistrer le paiement"
          variant="primaire"
          onPress={enregistrer}
        />
        {message ? <div style={styles.message}>{message}</div> : null}
      </Carte>
    </div>
  );
}

