  const reservationsFiltrees = useMemo(() => {
    if (filtre === 'Toutes') return reservations;
    return reservations.filter((r) => r.statut === filtre);
  }, [reservations, filtre]);

  const filtres: Array<'Toutes' | StatutReservation> = [
    'Toutes',
    'Confirmée',
    'En attente',
    'Échouée',
    'Retard',
