        <EtatVide
          titre="Aucune réservation"
          description="Modifiez le filtre pour afficher d'autres statuts."
        />
      ) : (
        reservationsFiltrees.map((r) => (
          <Carte key={r.id}>
            <div style={styles.ligneListe}>
              <div style={styles.colonneGauche}>
                <span style={TYPO.corps}>{r.client}</span>
                <span style={TYPO.petit}>
                  {r.reference} · {r.date} · {r.service}
