              </div>
              <div style={styles.colonneDroite}>
                <span style={TYPO.corps}>{formaterMontant(r.montant)}</span>
                <Pastille libelle={r.statut} couleur={couleurStatut(r.statut)} />
              </div>
            </div>
          </Carte>
        ))
      )}
    </div>
  );
}

function EcranAgentIA({
  paiements,
  reservations,
}: {
  paiements: Paiement[];
  reservations: Reservation[];
}) {
  const [requete, setRequete] = useState('');
  const [resultats, setResultats] = useState<
    Array<{ id: string; type: string; client: string; reference: string; montant: number; detail: string }>
  >([]);
  const [rechercheFaite, setRechercheFaite] = useState(false);

  const rechercher = () => {
    const terme = requete.trim().toLowerCase();
    if (!terme) {
      setResultats([]);
      setRechercheFaite(true);
      return;
    }
    const paiementsTrouves = paiements
      .filter(
        (p) =>
          p.client.toLowerCase().includes(terme) ||
          p.motif.toLowerCase().includes(terme) ||
          p.reference.toLowerCase().includes(terme),
      )
      .map((p) => ({
        id: `p-${p.id}`,
        type: 'Paiement',
        client: p.client,
        reference: p.reference,
        montant: p.montant,
        detail: p.motif,
      }));

    const reservationsTrouvees = reservations
      .filter(
        (r) =>
          r.client.toLowerCase().includes(terme) ||
          r.service.toLowerCase().includes(terme) ||
          r.reference.toLowerCase().includes(terme),
      )
      .map((r) => ({
        id: `r-${r.id}`,
        type: 'Réservation',
        client: r.client,
        reference: r.reference,
        montant: r.montant,
        detail: r.service,
      }));

    setResultats([...paiementsTrouves, ...reservationsTrouvees]);
    setRechercheFaite(true);
  };

  return (
    <div data-demonstration="true">
      <div style={styles.enteteEcran}>
        <Pastille libelle="Démonstration" couleur={SEMANTIQUE.information} />
      </div>
      <EnTeteDeSection
        titre="Agent IA de recherche"
        sousTitre="Recherche locale dans les paiements et réservations"
      />
      <Carte>
        <input
          type="text"
          value={requete}
          onChange={(e) => setRequete(e.target.value)}
          placeholder="Ex. : client, motif, service"
          style={styles.champTexte}
        />
        <Bouton libelle="Rechercher" variant="primaire" onPress={rechercher} />
      </Carte>

      {rechercheFaite && resultats.length === 0 ? (
        <EtatVide
          titre="Aucun résultat"
          description="Essayez une autre recherche ou vérifiez l'orthographe."
        />
      ) : (
        resultats.map((r) => (
          <Carte key={r.id}>
            <div style={styles.ligneListe}>
              <div style={styles.colonneGauche}>
                <span style={TYPO.corps}>{r.client}</span>
                <span style={TYPO.petit}>
                  {r.type} · {r.reference} · {r.detail}
                </span>
              </div>
              <span style={TYPO.corps}>{formaterMontant(r.montant)}</span>
            </div>
          </Carte>
        ))
      )}
    </div>
  );
}

