export default function App() {
  const [paiements, setPaiements] = useState<Paiement[]>(paiementsInitiaux);
  const [ecran, setEcran] = useState<Ecran>('accueil');
  const [largeur, setLargeur] = useState<number>(window.innerWidth);

  useEffect(() => {
    const redimensionner = () => setLargeur(window.innerWidth);
    window.addEventListener('resize', redimensionner);
    return () => window.removeEventListener('resize', redimensionner);
  }, []);

  const large = largeur >= 840;

  const ajouterPaiement = (client: string, montant: number, motif: string) => {
    const nouveau: Paiement = {
      id: String(Date.now()),
      reference: `PAY-2026-${String(paiements.length + 1).padStart(3, '0')}`,
      client,
      montant,
      date: new Date().toISOString().slice(0, 10),
      statut: 'Payé',
      motif,
    };
    setPaiements((precedents) => [nouveau, ...precedents]);
  };

  const navigation = [
    { libelle: 'Accueil', ecran: 'accueil' as Ecran, icone: 'accueil' },
    { libelle: 'Paiements', ecran: 'paiements' as Ecran, icone: 'argent' },
    { libelle: 'Réservations', ecran: 'reservations' as Ecran, icone: 'document' },
    { libelle: 'Agent IA', ecran: 'agent' as Ecran, icone: 'message' },
    { libelle: 'Profil', ecran: 'profil' as Ecran, icone: 'personne' },
  ];

  const afficherEcran = () => {
    switch (ecran) {
      case 'accueil':
        return (
          <EcranAccueil
            paiements={paiements}
            reservations={reservationsInitiales}
            largeur={largeur}
          />
        );
      case 'paiements':
        return <EcranPaiements paiements={paiements} onAjouterPaiement={ajouterPaiement} />;
      case 'reservations':
        return <EcranReservations reservations={reservationsInitiales} />;
      case 'agent':
        return <EcranAgentIA paiements={paiements} reservations={reservationsInitiales} />;
      case 'profil':
        return <EcranProfil />;
      default:
        return null;
    }
  };

  if (large) {
    return (
      <div style={styles.conteneurFlex}>
        <div style={styles.sidebar}>
          <span style={TYPO.h1}>Hayine</span>
          <div style={{ marginTop: ESPACE.xl, display: 'flex', flexDirection: 'column', gap: ESPACE.s }}>
            {navigation.map((item) => {
              const actif = ecran === item.ecran;
              return (
                <div
                  key={item.ecran}
                  onClick={() => setEcran(item.ecran)}
                  style={{
                    ...styles.itemNavVertical,
                    ...(actif ? styles.itemNavActif : styles.itemNavInactif),
                  }}
                >
                  <Icone nom={item.icone} taille={22} couleur={actif ? GRIS.carte : GRIS.texteSecondaire} />
                  <span style={TYPO.corps}>{item.libelle}</span>
                </div>
              );
            })}
          </div>
        </div>
        <div style={styles.principal}>{afficherEcran()}</div>
      </div>
    );
  }

  return (
    <div style={styles.conteneurColonne}>
